  // ------------------------------------------------------------ 组装 --
  function head(l) { return l.slice(0, l.indexOf('|')); }
  function classicCity(l) { return l + '|' + (NANMAN_CITIES.indexOf(head(l)) >= 0 ? 'nanman' : 'han'); }
  function classicFaction(l) { return l + '|' + (NANMAN_FACTIONS.indexOf(head(l)) >= 0 ? 'nanman' : 'han') + '|zhongyuan'; }
  function classicGeneral(l) { const n = head(l); return l + '|' + (NANMAN.indexOf(n) >= 0 ? 'nanman' : 'han') + '|' + (BORN[n] || ''); }

  const world = {
    StartYear: 190,
    StartMonth: 1,
    Title: '天下大势',
    Intro: "公元一九〇年，董卓专擅朝政，关东诸侯起兵讨伐，汉室天下分崩离析。\n东方，辽东公孙度自立为侯，朝鲜半岛诸国并起，倭国共立女王卑弥呼；北方草原上鲜卑、乌桓、匈奴各拥部众，西域诸城邦自成一方。\n葱岭以西，贵霜帝国由盛转衰，天竺南北诸国并立，安息王朝内乱不休；极西的罗马皇帝康茂德荒于政事，日耳曼与萨尔马提亚诸部窥伺于多瑙河畔，尼罗河上游的库施与红海之滨的阿克苏姆各据一方。\n东西万里，群雄并起，你将选择一位君主……",
    Cities: classic.Cities.map(classicCity).concat(CITIES),
    Links: classic.Links.concat(LINKS),
    SeaLinks: SEA,
    Factions: classic.Factions.map(classicFaction).concat(FACTIONS),
    Generals: classic.Generals.map(classicGeneral).concat(GENERALS),
    Regions: [{ id: 'zhongyuan', name: '中原', factions: classic.Factions.map(head) }].concat(REGIONS),
  };

  SG.Scenarios = { classic: classic, world: world };
  SG.GeneralBorn = BORN;

  // ------------------------------------------------------------ 查询 --
  const cultG = {}, cultC = {}, cultF = {}, regF = {};
  for (const l of world.Generals) { const p = l.split('|'); cultG[p[0]] = p[9] || 'han'; }
  for (const l of world.Cities) { const p = l.split('|'); cultC[p[0]] = p[10] || 'han'; }
  for (const l of world.Factions) { const p = l.split('|'); cultF[p[0]] = p[6] || 'han'; regF[p[0]] = p[7] || 'zhongyuan'; }
  SG.WorldData = {
    cultureOfGeneral(name) { return cultG[name] || 'han'; },
    cultureOfCity(key) { return cultC[key] || 'han'; },
    cultureOfFaction(key) { return cultF[key] || 'han'; },
    regionOfFaction(key) { return regF[key] || 'zhongyuan'; },
    sexOf(name) { const w = SG.WorldInfo[name]; return w ? w.sex : (CLASSIC_FEMALE.indexOf(name) >= 0 ? 'f' : 'm'); },
    bornOf(name) { const w = SG.WorldInfo[name]; const b = w ? w.born : BORN[name]; return b == null ? null : b; },
  };

